python3 << 'EOF'
import subprocess, json, base64, os

# Get the WS URL for target
tabs = subprocess.run(['curl', '-s', 'http://127.0.0.1:18800/json'], 
    capture_output=True, text=True)
tabs_data = json.loads(tabs.stdout)

target_id = "B1D22D5C6D65C3AA369FC7E9ED5C778D"
ws_url = None
for t in tabs_data:
    if t['id'] == target_id:
        ws_url = t['webSocketDebuggerUrl']
        break

